use std::ffi::CString;
use std::ptr::null_mut;
use ndk::media::media_codec::{MediaCodec, MediaCodecDirection};
use ndk_sys::{
    AMediaCodec, AMediaCodecBufferInfo, AMediaFormat,
        AMediaFormat_new, AMediaFormat_setString, AMediaFormat_setInt32,
            AMediaFormat_delete, AMediaCodec_createInputSurface,
                AMediaCodec_start, AMediaCodec_dequeueOutputBuffer,
                    AMediaCodec_getOutputBuffer, AMediaCodec_releaseOutputBuffer,
                        ANativeWindow
                        };

                        pub struct HardwareEncoderConfig {
                            pub width: i32,
                                pub height: i32,
                                    pub bit_rate: i32,
                                        pub frame_rate: i32,
                                            pub i_frame_interval_seconds: i32,
                                                pub mime_type: String,
                                                }

                                                pub struct HardwareEncoder {
                                                    codec: *mut AMediaCodec,
                                                        surface: *mut ANativeWindow,
                                                        }

                                                        impl HardwareEncoder {
                                                            /// Initializes an asynchronous or synchronized AMediaCodec hardware encoder instance
                                                                /// and configures an input surface for zero-copy rendering.
                                                                    pub fn new(config: HardwareEncoderConfig) -> Result<Self, String> {
                                                                            unsafe {
                                                                                        let mime = CString::new(config.mime_type.as_str()).map_err(|e| e.to_string())?;
                                                                                                    let codec = ndk_sys::AMediaCodec_createEncoderByType(mime.as_ptr());
                                                                                                                if codec.is_null() {
                                                                                                                                return Err("Failed to allocate AMediaCodec encoder instance".to_string());
                                                                                                                                            }

                                                                                                                                                        let format = AMediaFormat_new();
                                                                                                                                                                    if format.is_null() {
                                                                                                                                                                                    ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                    return Err("Failed to initialize AMediaFormat".to_string());
                                                                                                                                                                                                                }

                                                                                                                                                                                                                            // Configure baseline hardware parameters
                                                                                                                                                                                                                                        AMediaFormat_setString(format, ndk_sys::AMEDIAFORMAT_KEY_MIME, mime.as_ptr());
                                                                                                                                                                                                                                                    AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_WIDTH, config.width);
                                                                                                                                                                                                                                                                AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_HEIGHT, config.height);
                                                                                                                                                                                                                                                                            AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_BIT_RATE, config.bit_rate);
                                                                                                                                                                                                                                                                                        AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_FRAME_RATE, config.frame_rate);
                                                                                                                                                                                                                                                                                                    AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_I_FRAME_INTERVAL, config.i_frame_interval_seconds);
                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                            // COLOR_FormatSurface = 0x7F000789 indicates hardware surface input (Zero-Copy)
                                                                                                                                                                                                                                                                                                                                        AMediaFormat_setInt32(format, ndk_sys::AMEDIAFORMAT_KEY_COLOR_FORMAT, 0x7F000789);

                                                                                                                                                                                                                                                                                                                                                    let configure_status = ndk_sys::AMediaCodec_configure(
                                                                                                                                                                                                                                                                                                                                                                    codec,
                                                                                                                                                                                                                                                                                                                                                                                    format,
                                                                                                                                                                                                                                                                                                                                                                                                    null_mut(),
                                                                                                                                                                                                                                                                                                                                                                                                                    null_mut(),
                                                                                                                                                                                                                                                                                                                                                                                                                                    ndk_sys::AMEDIACODEC_CONFIGURE_FLAG_ENCODE as u32,
                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                            AMediaFormat_delete(format);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if configure_status != 0 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Err(format!("AMediaCodec configuration failed with code: {}", configure_status));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Create input surface directly from hardware encoder pipeline
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let mut surface: *mut ANativeWindow = null_mut();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let surface_status = AMediaCodec_createInputSurface(codec, &mut surface);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if surface_status != 0 || surface.is_null() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Err("Failed to acquire AMediaCodec native input window surface".to_string());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let start_status = AMediaCodec_start(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if start_status != 0 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ndk_sys::AMediaCodec_delete(codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Err("Failed to start hardware encoder".to_string());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Ok(Self { codec, surface })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pub fn get_input_surface(&self) -> *mut ANativeWindow {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        self.surface
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /// Pulls hardware-encoded NAL units from the encoder queue.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pub fn poll_packet(&self, timeout_us: i64) -> Option<(Vec<u8>, AMediaCodecBufferInfo)> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            unsafe {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let mut info = AMediaCodecBufferInfo {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        offset: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        size: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        presentationTimeUs: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        flags: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let index = AMediaCodec_dequeueOutputBuffer(self.codec, &mut info, timeout_us);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if index >= 0 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let mut buffer_size: usize = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let buffer_ptr = AMediaCodec_getOutputBuffer(self.codec, index as usize, &mut buffer_size);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let mut packet_data = Vec::with_capacity(info.size as usize);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if !buffer_ptr.is_null() && info.size > 0 {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let src = buffer_ptr.offset(info.offset as isize);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    std::ptr::copy_nonoverlapping(src, packet_data.as_mut_ptr(), info.size as usize);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        packet_data.set_len(info.size as usize);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AMediaCodec_releaseOutputBuffer(self.codec, index as usize, false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Some((packet_data, info))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    None
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            impl Drop for HardwareEncoder {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fn drop(&mut self) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        unsafe {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if !self.codec.is_null() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ndk_sys::AMediaCodec_stop(self.codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ndk_sys::AMediaCodec_delete(self.codec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }